-- ExamFlow institution server: database schema for Oracle Database 19c+
-- Schema version 2. Run it connected to the EMPTY database (or schema) made for ExamFlow,
-- as its owner or an admin. Safe to run twice. Then give the ExamFlow user the rights listed in DATABASES.md.

SET DEFINE OFF

-- ── step 1 ──
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE meta (k VARCHAR2(191 CHAR) PRIMARY KEY, v CLOB)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE docs (col VARCHAR2(64 CHAR) NOT NULL, id VARCHAR2(300 CHAR) NOT NULL, data CLOB NOT NULL, created NUMBER(19) NOT NULL, updated NUMBER(19) NOT NULL, CONSTRAINT pk_docs PRIMARY KEY (col, id), CONSTRAINT docs_json CHECK (data IS JSON))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
-- (speeds up searches; if your database refuses it, ExamFlow still works)
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX docs_examToken ON docs (col, JSON_VALUE(data, ''$.examToken'' RETURNING VARCHAR2(4000)))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
-- (speeds up searches; if your database refuses it, ExamFlow still works)
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX docs_teacherUid ON docs (col, JSON_VALUE(data, ''$.teacherUid'' RETURNING VARCHAR2(4000)))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
-- (speeds up searches; if your database refuses it, ExamFlow still works)
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX docs_switchCode ON docs (col, JSON_VALUE(data, ''$.switchCode'' RETURNING VARCHAR2(4000)))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE users ("uid" VARCHAR2(191 CHAR) PRIMARY KEY, email VARCHAR2(320 CHAR) NOT NULL UNIQUE, name VARCHAR2(4000), pass_hash VARCHAR2(4000), source VARCHAR2(32 CHAR) NOT NULL, oidc_sub VARCHAR2(4000), created NUMBER(19) NOT NULL, disabled NUMBER(1) DEFAULT 0 NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE codes (code_hash VARCHAR2(191 CHAR) PRIMARY KEY, email VARCHAR2(4000) NOT NULL, purpose VARCHAR2(4000) NOT NULL, created NUMBER(19) NOT NULL, expires NUMBER(19) NOT NULL, used NUMBER(19))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE logins (token_hash VARCHAR2(191 CHAR) PRIMARY KEY, "uid" VARCHAR2(4000) NOT NULL, created NUMBER(19) NOT NULL, expires NUMBER(19) NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE oidc_state (state VARCHAR2(191 CHAR) PRIMARY KEY, nonce VARCHAR2(4000) NOT NULL, verifier VARCHAR2(4000) NOT NULL, created NUMBER(19) NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE allowlist (teacher_id VARCHAR2(191 CHAR) PRIMARY KEY, email VARCHAR2(320 CHAR) NOT NULL UNIQUE, name VARCHAR2(4000), version NUMBER(10) NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE allowlist_history (n NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, t NUMBER(19) NOT NULL, package_id VARCHAR2(4000), package_version VARCHAR2(4000), list_version NUMBER(10), added NUMBER(10), removed NUMBER(10), total NUMBER(10))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE "audit" (n NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, t NUMBER(19) NOT NULL, actor VARCHAR2(4000), action VARCHAR2(4000) NOT NULL, target CLOB, result VARCHAR2(4000) NOT NULL, detail CLOB)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/
-- append-only protection for the audit log (audit_append_only)
CREATE OR REPLACE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON "audit" BEGIN RAISE_APPLICATION_ERROR(-20001, 'the audit log is append-only'); END;
/

-- ── step 2 ──
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE inbox (msg_id VARCHAR2(191 CHAR) NOT NULL, email VARCHAR2(320 CHAR) NOT NULL, delivered_at NUMBER(19), read_at NUMBER(19), archived_at NUMBER(19), CONSTRAINT pk_inbox PRIMARY KEY (msg_id, email))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955, -1408, -2260, -2261, -2275) THEN RAISE; END IF; END;
/

-- record which schema version this database has
MERGE INTO meta t USING dual ON (t.k = 'schema_version') WHEN MATCHED THEN UPDATE SET t.v = '2' WHEN NOT MATCHED THEN INSERT (k, v) VALUES ('schema_version', '2')
/

COMMIT
/
